/**
 * Health
 *
 * Ilova tirikmi (liveness).
 *
 * Ataylab bazaga tegmaydi: baza yiqilganda ham ilovaning oʻzi tirik va
 * systemd uni qayta ishga tushirishi shart emas. Bazaga tegadigan
 * tekshiruv — `/health/ready`.
 */
export const serviceHealth = <ThrowOnError extends boolean = false>(options?: Options<ServiceHealthData, ThrowOnError>): RequestResult<ServiceHealthResponses, unknown, ThrowOnError> => (options?.client ?? client).get<ServiceHealthResponses, unknown, ThrowOnError>({ url: '/health', ...options });

/**
 * Readiness
 *
 * Soʻrov qabul qilishga tayyormi (readiness).
 *
 * Bazaga haqiqiy soʻrov yuboradi. Baza yiqilgan boʻlsa `503` qaytaradi —
 * Caddy/systemd shunda trafikni yubormaydi va sabab logda koʻrinadi.
 */
export const serviceReadiness = <ThrowOnError extends boolean = false>(options?: Options<ServiceReadinessData, ThrowOnError>): RequestResult<ServiceReadinessResponses, unknown, ThrowOnError> => (options?.client ?? client).get<ServiceReadinessResponses, unknown, ThrowOnError>({ url: '/health/ready', ...options });
